'use strict';
function attendeeLabel(n){return n+' '+(n===1?'attendee':'attendees')}

function frequencyBadge(m,t=m.trap){if(!t)return 'Other members';const a=Hive.attendanceStats(state,m,t);return a.rate!==null?`${Math.round(a.rate*100)}% · ${a.attended}/${a.count} ${a.count===1?'event':'events'} · ${a.label}`:`${a.label} · ${a.source==='manual'?'Manual code':'No complete records'}`;}

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='bear-hive-v1';let state,readonly=false,undo=[],redo=[],selectedMember=null,selectedSlot=null,activeTrap='1',tool='select',iso=false,page='map',camera={x:0,y:0,k:1},view={w:800,h:470},moveTarget=null,history=[];
try{state=Hive.validate(JSON.parse(localStorage.getItem(KEY)));history=JSON.parse(localStorage.getItem(KEY+'-history')||'[]')}catch{state=Hive.emptyPlan()}
if(location.hash.startsWith('#plan=')){try{const decoded=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(location.hash.slice(6)),c=>c.charCodeAt(0))));state=Hive.validate(decoded);readonly=true;document.body.classList.add('viewer')}catch{setTimeout(()=>toast('This shared plan could not be read.'),100)}}
Hive.migrate(state);if(!state.mapMode)state.mapMode='plain';if(state.mapMode==='terrain')activeTrap='all';Hive.worldOrigin(state);
if(localStorage.getItem(KEY+'-dark')==='true')document.body.classList.add('dark');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(){if(readonly)return;try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(KEY+'-history',JSON.stringify(history.slice(-10)));$('#saveState').textContent='Saved on this device'}catch{$('#saveState').textContent='Not saved · storage full';toast('Save failed. Download a backup now.')}}
function commit(fn){if(readonly)return;undo.push(JSON.stringify(state));if(undo.length>40)undo.shift();redo=[];history.push({at:new Date().toISOString(),state:JSON.stringify(state)});fn();persist();render()}
function openModal(html){$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){$('#modal').close();moveTarget=null}
$('#closeModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
function slotBy(id){return state.slots.find(s=>s.id===id)}function memberAt(id){return state.members.find(m=>m.slot===id)}
function slotLabel(id){const s=slotBy(id);if(!s)return 'Unassigned';const c=Hive.coord(state,s);return `BT ${s.trap} · Row ${s.row} · X:${c.x} Y:${c.y}`}
function pending(m){const s=slotBy(m.slot);if(!s)return false;const c=Hive.coord(state,s);return !m.current||m.current.x!==c.x||m.current.y!==c.y}
function render(){const t=state.settings;$('#workspaceName').textContent=`State ${t.state} · Officer workspace`;$('#time1').textContent=t.time1+' UTC';$('#time2').textContent=t.time2+' UTC';$('#memberCount').textContent=state.members.length;$('#moveCount').textContent=state.members.filter(pending).length;$('#placedStat').textContent=state.members.filter(m=>m.slot).length+' / '+state.members.length;$('#activeStat').textContent=state.members.filter(m=>Hive.attendanceScore(state,m,m.trap)>=.7).length;$('#openStat').textContent=state.slots.filter(s=>!memberAt(s.id)&&!Hive.worldBlocked(state,s)).length;$('#undoBtn').disabled=!undo.length;$('#redoBtn').disabled=!redo.length;$('#geometryLabel').textContent=t.verified?'Coordinate mapping marked verified':'2×2 city · 3×3 trap · model units';$('#mapBadge').textContent=(activeTrap==='all'?'Both traps':'BT '+activeTrap)+(readonly?' · Shared snapshot':' · Draft layout');renderMap();renderQueue();renderMembers();renderMoves();if(page==='settings')fillSettings()}
function navigate(p){page=p;$$('.page').forEach(el=>el.classList.toggle('hidden',el.id!=='page-'+p));$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));const meta={map:['HIVE MAP','Hive map','Place cities and assign players.'],members:['PLAYERS','Players','Manage players and BT groups.'],moves:['RELOCATION','Move instructions','Copy planned positions and confirm moves.'],attendance:['ATTENDANCE','Attendance',''],settings:['SETTINGS','Settings','Schedules, coordinates and backups.']}[p];$('#pageEyebrow').textContent=meta[0];$('#pageTitle').textContent=meta[1];$('#pageIntro').textContent=meta[2];render();if(p==='map')setTimeout(fit,0)}
$$('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#allMembers').onclick=()=>navigate('members');$('#setupBtn').onclick=()=>navigate('settings');
function projected(x,y){return iso?{x:(x-y)*.82,y:(x+y)*.46}:{x,y}}
function inverse(x,y){return iso?{x:x/(2*.82)+y/(2*.46),y:y/(2*.46)-x/(2*.82)}:{x,y}}
function point(x,y){const p=projected(x,y);return{x:camera.x+p.x*camera.k,y:camera.y+p.y*camera.k}}
function screenWorld(x,y){return inverse((x-camera.x)/camera.k,(y-camera.y)/camera.k)}
function polygon(o){return[[o.x,o.y],[o.x+o.w,o.y],[o.x+o.w,o.y+o.h],[o.x,o.y+o.h]].map(([x,y])=>{const p=point(x,y);return`${p.x},${p.y}`}).join(' ')}
function visible(o){return activeTrap==='all'||!o.trap||String(o.trap)===activeTrap}
function renderMap(){const svg=$('#mapSvg');const box=$('#mapViewport').getBoundingClientRect();view={w:box.width||800,h:box.height||470};svg.setAttribute('viewBox',`0 0 ${view.w} ${view.h}`);let parts=[];
const corners=[[0,0],[view.w,0],[0,view.h],[view.w,view.h]].map(([x,y])=>screenWorld(x,y)),bx=Math.floor(Math.min(...corners.map(p=>p.x)))-1,by=Math.floor(Math.min(...corners.map(p=>p.y)))-1;const bounds={x:bx,y:by,w:Math.ceil(Math.max(...corners.map(p=>p.x)))-bx+1,h:Math.ceil(Math.max(...corners.map(p=>p.y)))-by+1};for(let x=bounds.x;x<=bounds.x+bounds.w;x++){const a=point(x,bounds.y),b=point(x,bounds.y+bounds.h);parts.push(`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#819777" stroke-opacity=".13"/>`)}for(let y=bounds.y;y<=bounds.y+bounds.h;y++){const a=point(bounds.x,y),b=point(bounds.x+bounds.w,y);parts.push(`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#819777" stroke-opacity=".13"/>`)}
const wx=Math.floor(Math.min(...corners.map(p=>p.x)))-1,wy=Math.floor(Math.min(...corners.map(p=>p.y)))-1;const fixed=Hive.worldFeatures(state,{x:wx,y:wy,w:Math.ceil(Math.max(...corners.map(p=>p.x)))-wx+1,h:Math.ceil(Math.max(...corners.map(p=>p.y)))-wy+1});for(const f of fixed)parts.push(`<polygon data-fixed-feature="${f.key}" points="${polygon(f)}" fill="${f.color}" fill-opacity="${[5,6].includes(f.key)?.25:.75}" stroke="${f.color}" stroke-width=".4" pointer-events="none"/>`);
for(const b of state.blocks){if(!visible(b))continue;const c=point(b.x+b.w/2,b.y+b.h/2);parts.push(`<polygon points="${polygon(b)}" fill="#a8b0a0" stroke="#84937c" stroke-width="1"/><text x="${c.x}" y="${c.y+4}" text-anchor="middle" font-size="11" fill="#53634e">⛰️</text>`)}
for(const s of state.slots){if(!visible(s))continue;const m=memberAt(s.id),c=point(s.x+1,s.y+1),chosen=selectedSlot===s.id||selectedMember===m?.id;const blocked=Hive.worldBlocked(state,s);let fill=m?(Hive.attendanceScore(state,m,m.trap)>=.7?'#799677':'#b5beaa'):blocked?'#ddb4a6':'#e5ebdd';let stroke=chosen?'#263e31':m?'#f4f6ed':'#acba9e';parts.push(`<g data-slot="${s.id}" tabindex="0" role="button" aria-label="${esc(m?m.name: 'Open city slot')}, row ${s.row}"><polygon points="${polygon(s)}" fill="${fill}" fill-opacity="${m?1:.6}" stroke="${stroke}" stroke-width="${chosen?3:m?2:1}" ${m?'':'stroke-dasharray="3 3"'}/>`);if(camera.k>12){const fs=Math.max(11,Math.min(12,camera.k*.4));const maxChars=Math.max(2,Math.floor((camera.k*2-8)/(fs*.56)));const label=m?Array.from(m.name).length>maxChars?Array.from(m.name).slice(0,maxChars-1).join('')+'…':m.name:blocked?'×':'＋';parts.push(`<text x="${c.x}" y="${c.y+(m?-2:4)}" text-anchor="middle" font-family="-apple-system, sans-serif" font-size="${fs}" font-weight="${m?550:400}" fill="${m?'#243d30':'#94a587'}" pointer-events="none">${esc(label)}</text>`);if(m&&camera.k>17)parts.push(`<text x="${c.x}" y="${c.y+12}" text-anchor="middle" font-size="8" fill="#344a38" pointer-events="none">${'BT '+s.trap}</text>`)}if(m?.locked&&camera.k>10){const lock=point(s.x+1.65,s.y+.25);parts.push(`<g data-lock-marker="true" transform="translate(${lock.x-6} ${lock.y-5})" aria-hidden="true"><rect width="12" height="12" rx="2" fill="#f4f6ed"/><path d="M3.5 5V3.5a2.5 2.5 0 0 1 5 0V5M3 5h6v5H3Z" fill="none" stroke="#263e31" stroke-width="1.2" stroke-linejoin="round"/></g>`)}parts.push('</g>')}
for(const t of state.traps){if(activeTrap!=='all'&&String(t.id)!==activeTrap)continue;const c=point(t.x+1.5,t.y+1.5);parts.push(`<g data-trap-id="${t.id}"><polygon points="${polygon(t)}" fill="#315840" stroke="#f4f6ed" stroke-width="3"/><text x="${c.x}" y="${c.y-5}" text-anchor="middle" font-size="${Math.min(24,camera.k)}" fill="#e7eee1" pointer-events="none">✥</text><text x="${c.x}" y="${c.y+14}" text-anchor="middle" font-size="10" font-weight="650" fill="#e7eee1" pointer-events="none">BEAR ${t.id}</text></g>`)}
for(const o of state.structures){const c=point(o.x+o.w/2,o.y+o.h/2);parts.push(`<g data-object="${o.id}"><polygon points="${polygon(o)}" fill="#8a9a7d" stroke="#f4f6ed" stroke-width="2"/><text x="${c.x}" y="${c.y+4}" text-anchor="middle" font-size="12" fill="#fff">${o.kind==='hq'?'HQ':o.kind==='node'?'Node':'⚑'}</text></g>`)}svg.innerHTML=parts.join('');svg.querySelectorAll('[data-slot]').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();handleSlot(el.dataset.slot)}})}
function fit(){const box=$('#mapViewport').getBoundingClientRect();if(!box.width)return;const objects=[...state.slots,...state.traps.filter(t=>activeTrap==='all'||String(t.id)===activeTrap),...state.blocks,...state.structures].filter(visible);if(!objects.length){const o=Hive.worldOrigin(state),p=projected(500-o.x,500-o.y);camera.k=Math.min((box.width-35)/28,(box.height-80)/28);camera.x=box.width/2-p.x*camera.k;camera.y=box.height/2-p.y*camera.k;renderMap();return}const focus=state.traps.filter(t=>activeTrap==='all'||String(t.id)===activeTrap);objects.push(...focus.map(t=>({x:t.x-12,y:t.y-12,w:27,h:27})));const pts=objects.flatMap(o=>[projected(o.x,o.y),projected(o.x+o.w,o.y),projected(o.x,o.y+o.h),projected(o.x+o.w,o.y+o.h)]);const minX=Math.min(...pts.map(p=>p.x))-1,maxX=Math.max(...pts.map(p=>p.x))+1,minY=Math.min(...pts.map(p=>p.y))-1,maxY=Math.max(...pts.map(p=>p.y))+1;camera.k=Math.min((box.width-35)/(maxX-minX),(box.height-80)/(maxY-minY));camera.x=(box.width-(minX+maxX)*camera.k)/2;camera.y=(box.height-(minY+maxY)*camera.k)/2+10;renderMap()}
function zoom(f,cx=view.w/2,cy=view.h/2){const k=Math.min(100,Math.max(5,camera.k*f));const r=k/camera.k;camera.x=cx-(cx-camera.x)*r;camera.y=cy-(cy-camera.y)*r;camera.k=k;renderMap()}
$('#zoomIn').onclick=()=>zoom(1.25);$('#zoomOut').onclick=()=>zoom(.8);$('#fitBtn').onclick=fit;$('#viewBtn').onclick=()=>{iso=!iso;$('#viewBtn').textContent=iso?'▦ Top down':'◇ Isometric';fit()};$$('#trapTabs button').forEach(b=>b.onclick=()=>{activeTrap=b.dataset.trap;$$('#trapTabs button').forEach(el=>el.classList.toggle('active',el===b));render();fit()});
function setTool(t){tool=t;moveTarget=null;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#mapHint').textContent=({select:'Drag to pan · Tap an item to select · Pinch to zoom',assign:'Choose a member, then tap their city slot',block:'Tap empty space to add terrain.',flag:'Tap an empty tile to place a banner',hq:'Tap an empty area to place a 3×3 HQ',slot:'Tap an empty area to add a city',remove:'Tap a city, terrain, banner or HQ to remove it',move:'Tap a free grid position to move this city'})[t]||''}
$$('[data-tool]').forEach(b=>b.onclick=()=>{if(b.dataset.tool==='flag'){openModal('<div class="eyebrow">ALLIANCE STRUCTURES</div><h2>What are you placing?</h2><p>Place a footprint on an empty area. Empty city slots will be removed where needed.</p><div class="sheet-list"><button id="chooseBanner">⚑ Banner · 1×1</button><button id="chooseHQ">⌂ Alliance HQ · 3×3</button></div><div class="notice">Territory influence and connectivity are not validated.</div>');$('#chooseBanner').onclick=()=>{setTool('flag');closeModal()};$('#chooseHQ').onclick=()=>{setTool('hq');closeModal()}}else setTool(b.dataset.tool)});
function mapTap(e,target){if(target.closest('.map-controls'))return;const rect=$('#mapViewport').getBoundingClientRect();const p=screenWorld(e.clientX-rect.left,e.clientY-rect.top);const at={x:Math.floor(p.x),y:Math.floor(p.y),w:1,h:1};const s=state.slots.find(s=>visible(s)&&p.x>=s.x&&p.x<s.x+2&&p.y>=s.y&&p.y<s.y+2);
if(readonly){if(s)handleSlot(s.id);return}
const hitTrap=state.traps.find(t=>visible({...t,trap:t.id})&&Hive.overlap(at,t));if(hitTrap&&tool==='select'){trapDetails(hitTrap.id);return}
const mapOrigin=Hive.worldOrigin(state),fixedKey=state.mapMode==='terrain'?Hive.worldAt(mapOrigin.x+at.x,mapOrigin.y+at.y):0;if(fixedKey&&!s&&!state.blocks.some(b=>Hive.overlap(at,b))&&!state.structures.some(b=>Hive.overlap(at,b))&&['remove','select','block'].includes(tool)){if(tool==='select'){const f=Hive.worldFeatures(state,at)[0];openModal(`<div class="eyebrow">FIXED WORLD MAP</div><h2>${esc(f?.name||'Map feature')}</h2><p>X:${mapOrigin.x+at.x} Y:${mapOrigin.y+at.y}</p><p>Fixed WOS Nerds map feature. Its position and footprint cannot be edited.</p><p>${[5,6].includes(fixedKey)?'Cities are allowed in this shaded area. Other placement rules may apply.':'City placement is blocked here.'}</p>`)}else toast('Fixed world-map features cannot be removed or altered.');return}
if(tool==='remove'){const b=state.blocks.find(b=>Hive.overlap(at,b)),o=state.structures.find(o=>Hive.overlap(at,o));try{const target=s?{slotId:s.id}:b?{terrainId:b.id}:o?{objectId:o.id}:null;if(target){const next=Hive.removeMapObject(state,target);commit(()=>state=next)}else{toast('Select a city, terrain, banner or HQ. Bear Trap references remain fixed.');return}toast('Removed from map. Undo is available.')}catch(e){toast(e.message)}return}

if(tool==='move'&&moveTarget){applyCityMove(moveTarget,Math.floor(p.x),Math.floor(p.y));return}
if(tool==='select'||tool==='assign'||tool==='move'){if(s){handleSlot(s.id);return}const obj=state.structures.find(b=>Hive.overlap(at,b));if(obj)objectModal(obj);else {const b=state.blocks.find(b=>Hive.overlap(at,b));if(b)objectModal(b,true)}return}
if(tool==='block'&&state.mapMode==='terrain'&&Hive.worldAt(Hive.worldOrigin(state).x+at.x,Hive.worldOrigin(state).y+at.y)){toast('The fixed world-map layer cannot be changed.');return}
if(tool==='block'){const b=state.blocks.find(b=>Hive.overlap(at,b));if(b){commit(()=>state.blocks=state.blocks.filter(o=>o!==b));return}if(state.traps.some(t=>Hive.overlap(at,t))||state.structures.some(t=>Hive.overlap(at,t))||state.slots.some(t=>Hive.overlap(at,t)&&memberAt(t.id))){toast('This tile is occupied. Move the city first.');return}commit(()=>{state.slots=state.slots.filter(t=>!Hive.overlap(at,t));state.blocks.push({...at,id:crypto.randomUUID()})});return}
if(tool==='slot'&&!state.traps.length){toast('Place a bear trap by coordinates before adding city spaces.');return}const obj={...at,w:tool==='slot'?2:tool==='hq'?3:1,h:tool==='slot'?2:tool==='hq'?3:1,id:crypto.randomUUID()};if(Hive.worldBlocked(state,obj,tool==='slot'?'city':tool)||[...state.traps,...state.structures,...state.blocks,...state.slots.filter(s=>tool==='slot'||memberAt(s.id))].some(t=>Hive.overlap(obj,t))){toast('That footprint overlaps another object.');return}commit(()=>{if(tool==='flag'||tool==='hq'){obj.kind=tool;state.slots=state.slots.filter(t=>!Hive.overlap(obj,t));state.structures.push(obj)}else{const t=[...state.traps].sort((a,b)=>Math.hypot(a.x-obj.x,a.y-obj.y)-Math.hypot(b.x-obj.x,b.y-obj.y))[0];obj.trap=t.id;const a=Hive.center(obj),b=Hive.center(t);obj.row=Math.max(1,Math.ceil((Math.max(Math.abs(a.x-b.x),Math.abs(a.y-b.y))-1.5)/2));state.slots.push(obj)}})}
function objectModal(o,block=false){openModal(`<div class="eyebrow">MAP OBJECT</div><h2>${block?'Blocked terrain':o.kind==='hq'?'Alliance HQ':o.kind==='node'?'Resource node':'Banner'}</h2><p>X:${Hive.coord(state,o).x} Y:${Hive.coord(state,o).y}</p><p>${block?'Terrain is a planning constraint.':'Structure footprint only. Territory connectivity is not validated.'}</p><button class="danger" id="deleteObject">Remove object</button>`);$('#deleteObject').onclick=()=>{commit(()=>{if(block)state.blocks=state.blocks.filter(b=>b.id!==o.id);else state.structures=state.structures.filter(b=>b.id!==o.id)});closeModal()}}
function handleSlot(id){selectedSlot=id;const m=memberAt(id),s=slotBy(id);if(readonly){if(m)memberView(m);else toast('This spot is available.');return}
if(tool==='move'&&moveTarget){const moving=state.members.find(m=>m.id===moveTarget);if(!Hive.validCityPosition(state,s,moving.id)){toast('This city space overlaps a fixed map feature or another city.');return}if(moving.locked){toast('Unlock this member before moving.');return}if(m&&m.id!==moving.id){toast('Choose an empty slot.');return}if(s.trap!==moving.trap){toast('Change the member’s trap before assigning here.');return}commit(()=>{moving.slot=id;moving.confirmed=false;moving.verified=false});setTool('select');toast('City assignment moved.');return}
if(tool==='assign'&&selectedMember){const chosen=state.members.find(m=>m.id===selectedMember);if(!Hive.validCityPosition(state,s,chosen.id)){toast('This city space overlaps a fixed map feature or another city.');return}if(chosen.locked){toast('This member is locked.');return}if(m&&m.id!==chosen.id){toast('Spot already assigned. Choose an open spot.');return}if(chosen.trap!==s.trap){toast('This member belongs to the other trap. Edit their trap first.');return}commit(()=>{chosen.slot=id;chosen.confirmed=false;chosen.verified=false});toast(chosen.name+' assigned');return}
renderMap();if(m)memberDetail(m.id);else openSlot(id)}
function openSlot(id){openModal(`<div class="eyebrow">AVAILABLE CITY SPOT</div><h2>Make room for a regular.</h2><div class="coordinate">${esc(slotLabel(id))}</div><label>Assign a member<select id="slotMember"><option value="">Choose a member…</option>${state.members.filter(m=>m.trap===slotBy(id).trap&&!m.locked).map(m=>`<option value="${esc(m.id)}">${esc(m.name)}${m.slot?' · already placed':''}</option>`).join('')}</select></label><div class="actions"><button class="primary" id="assignSlot">Assign member</button><button id="removeSlot">Remove empty slot</button></div>`);$('#assignSlot').onclick=()=>{const m=state.members.find(m=>m.id===$('#slotMember').value);if(!m){toast('Choose a member first.');return}if(!Hive.validCityPosition(state,slotBy(id),m.id)){toast('This city space overlaps a fixed map feature or another city.');return}commit(()=>{m.slot=id;m.confirmed=false;m.verified=false});closeModal()};$('#removeSlot').onclick=()=>{commit(()=>state.slots=state.slots.filter(s=>s.id!==id));closeModal()}}
function renderQueue(){const q=$('#queueSearch').value.toLowerCase();$('#queue').innerHTML=state.members.filter(m=>String(m.trap)===String(state.operations.rosterGroup)).filter(m=>(m.name+' '+m.playerId).toLowerCase().includes(q)).map(m=>`<button class="queue-row ${selectedMember===m.id?'active':''}" data-member="${esc(m.id)}"><span class="avatar">${esc(m.name.slice(0,1))}</span><span>${esc(m.name)}<small>${esc(frequencyBadge(m,m.trap))}</small></span><span>${m.slot?'R'+slotBy(m.slot)?.row:'＋'}</span></button>`).join('')||'<p class="muted">No members found.</p>';$$('#queue [data-member]').forEach(b=>b.onclick=()=>{selectedMember=b.dataset.member;if(!state.members.find(m=>m.id===selectedMember).trap){memberDetail(selectedMember);return}setTool('assign');renderQueue();renderMap();toast('Tap an open city slot to assign '+state.members.find(m=>m.id===selectedMember).name)})}
$('#queueSearch').oninput=renderQueue;
function renderMembers(){const q=$('#memberSearch').value.toLowerCase(),f=$('#memberFilter').value;const ms=state.members.filter(m=>(m.name+' '+m.playerId).toLowerCase().includes(q)).filter(m=>f==='all'||f==='unassigned'&&!m.slot||String(m.trap)===f&&Hive.attendanceScore(state,m,m.trap)>=.7);$('#memberList').innerHTML=ms.map(m=>`<button class="member-card" data-id="${esc(m.id)}"><span class="avatar">${esc(m.name.slice(0,1))}</span><span><strong>${esc(m.name)} ${m.locked?'⌑':''}</strong><small>${esc(slotLabel(m.slot))}</small><span class="pill">${esc(frequencyBadge(m,m.trap))}</span></span></button>`).join('')||'<div class="empty-state">No members match this view. Add a member or import your roster.</div>';$$('#memberList [data-id]').forEach(b=>b.onclick=()=>memberDetail(b.dataset.id))}
$('#memberSearch').oninput=()=>renderMembers();$('#memberFilter').onchange=()=>renderMembers();
function locateMember(m){closeModal();selectedMember=m.id;selectedSlot=m.slot;activeTrap=String(m.trap);$$('#trapTabs button').forEach(b=>b.classList.toggle('active',b.dataset.trap===activeTrap));navigate('map');setTimeout(()=>{const s=slotBy(m.slot);if(s){const p=projected(s.x+1,s.y+1);camera.k=Math.max(camera.k,24);camera.x=view.w/2-p.x*camera.k;camera.y=view.h/2-p.y*camera.k;renderMap()}else toast('This member has no assigned spot.')},20)}
function memberForm(existing=null){const m=existing||{id:crypto.randomUUID(),name:'',playerId:'',alliance:state.settings.alliance,trap:state.operations.rosterGroup,priority:0,attendance:{1:{kind:'unknown'},2:{kind:'unknown'}},slot:null,current:null,locked:false,confirmed:false,verified:false,notes:''};const opts=(t)=>[['unknown','Unknown'],['regular','Frequently'],['sometimes','Sometimes'],['rarely','Rarely']].map(([v,l])=>`<option value="${v}" ${m.attendance[t]?.kind===v?'selected':''}>${l}</option>`).join('');openModal(`<div class="eyebrow">PLAYER RECORD</div><h2>${existing?esc(m.name):'Add a player'}</h2><form id="memberForm"><label>Username<input name="name" value="${esc(m.name)}" required maxlength="80"></label><div class="two"><label>Player ID<input name="playerId" value="${esc(m.playerId)}" inputmode="numeric" pattern="[0-9]*"></label><label>Roster group<select name="trap"><option value="0" ${m.trap===0?'selected':''}>Other members</option><option value="1" ${m.trap===1?'selected':''}>BT 1</option><option value="2" ${m.trap===2?'selected':''}>BT 2</option></select></label></div><div class="two"><label>BT 1 manual frequency<select name="kind1">${opts(1)}</select></label><label>BT 2 manual frequency<select name="kind2">${opts(2)}</select></label></div><p>Manual frequency applies until this trap has a completed, eligible attendance record.</p><label class="check"><input name="autoBTGroup" type="checkbox" ${m.btGroupMode!=='manual'?'checked':''}> Update BT list from attendance</label><div class="two"><label>Current X<input name="currentX" type="number" value="${m.current?.x??''}"></label><label>Current Y<input name="currentY" type="number" value="${m.current?.y??''}"></label></div><label>Officer priority (0–10)<input name="priority" type="number" min="0" max="10" value="${m.priority||0}"></label><details><summary>Alliance metadata</summary><label>Alliance tag<input name="alliance" maxlength="20" value="${esc(m.alliance||state.settings.alliance)}"></label></details><label>Notes<textarea name="notes" maxlength="2000">${esc(m.notes)}</textarea></label><div class="actions"><button class="primary" type="submit">Save player</button>${existing?'<button class="danger" id="deleteMember" type="button">Delete player</button>':''}</div></form>`);$('#memberForm').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!v.name.trim())return;if((v.currentX==='')!==(v.currentY==='')){toast('Enter both coordinates or leave both blank.');return}if(v.playerId&&state.members.some(p=>p.id!==m.id&&p.playerId===v.playerId)){toast('That player ID already belongs to another player.');return}if(+v.trap!==m.trap&&m.locked){toast('Unlock the city before changing traps.');return}const n={...m,btGroupMode:v.autoBTGroup==='on'?'attendance':'manual',name:v.name.trim(),playerId:v.playerId.trim(),alliance:v.alliance.trim(),trap:+v.trap,priority:+v.priority,notes:v.notes,current:v.currentX===''?null:{x:+v.currentX,y:+v.currentY},attendance:{}};for(const t of [1,2])n.attendance[t]=v['kind'+t]===m.attendance[t]?.kind?m.attendance[t]:{kind:v['kind'+t],attended:null,total:null};if(n.trap!==m.trap){n.btGroupMode='manual';delete n.suggestedAttendanceTrap;n.slot=null;n.confirmed=false;n.verified=false}commit(()=>{if(existing)state.members=state.members.map(p=>p.id===m.id?n:p);else state.members.push(n)});closeModal();toast('Player saved')};if(existing)$('#deleteMember').onclick=()=>{openModal(`<h2>Remove ${esc(m.name)}?</h2><p>Attendance history is retained. Undo is available.</p><button class="danger" id="confirmDelete">Remove player</button>`);$('#confirmDelete').onclick=()=>{commit(()=>state.members=state.members.filter(p=>p.id!==m.id));closeModal()}}}
$('#addMember').onclick=$('#addQuick').onclick=()=>memberForm();
function renderMoves(){const ms=state.members.filter(m=>m.slot);$('#moveList').innerHTML=`<div class="notice">${state.settings.verified?'Coordinate mapping marked verified.':'Coordinate mapping is unverified. Check the map reference before relocating.'} Confirmations are recorded on this device. An unknown current position is shown separately from a confirmed relocation.</div>`+ms.map(m=>`<div class="move-row"><span class="avatar">${esc(m.name.slice(0,1))}</span><div><strong>${esc(m.name)}</strong><small>${esc(slotLabel(m.slot))}</small><small>${m.current?`Current X:${m.current.x} Y:${m.current.y}${pending(m)?' · Move needed':' · Already in position'}`:'Current coordinates not recorded'}</small></div><div class="checks"><label class="check"><input type="checkbox" data-confirm="${esc(m.id)}" ${m.confirmed?'checked':''}> Member confirmed</label><label class="check"><input type="checkbox" data-verify="${esc(m.id)}" ${m.verified?'checked':''}> Officer verified</label></div><button data-show="${esc(m.id)}">View spot</button></div>`).join('');if(!ms.length)$('#moveList').innerHTML+='<div class="empty-state">Assign members to start your relocation checklist.</div>';$$('[data-confirm]').forEach(el=>el.onchange=()=>commit(()=>state.members.find(m=>m.id===el.dataset.confirm).confirmed=el.checked));$$('[data-verify]').forEach(el=>el.onchange=()=>commit(()=>state.members.find(m=>m.id===el.dataset.verify).verified=el.checked));$$('[data-show]').forEach(el=>el.onclick=()=>memberView(state.members.find(m=>m.id===el.dataset.show)))}
function memberView(m){officerInstructions(m)}
$('#findBtn').onclick=()=>{openModal('<div class="eyebrow">FIND YOUR PLACE</div><h2>Find a player.</h2><input id="findInput" placeholder="Search your name…" aria-label="Find your city"><div class="sheet-list" id="findResults"></div>');const show=()=>{$('#findResults').innerHTML=state.members.filter(m=>m.name.toLowerCase().includes($('#findInput').value.toLowerCase())).map(m=>`<button data-find="${esc(m.id)}">${esc(m.name)}<small class="muted">${esc(slotLabel(m.slot))}</small></button>`).join('')||'<p>No member found.</p>';$$('[data-find]').forEach(b=>b.onclick=()=>memberView(state.members.find(m=>m.id===b.dataset.find)))};$('#findInput').oninput=show;show();$('#findInput').focus()};
$('#suggestBtn').onclick=()=>{const proposal=Hive.suggest(state,activeTrap);const moved=proposal.changes.length;openModal(`<div class="eyebrow">ASSIGNMENT PREVIEW</div><h2>${moved?moved+' suggested '+(moved===1?'change.':'changes.'):!state.slots.length?'Add city spaces first':!state.members.length?'Add members first':'No assignment changes'}</h2><p>Assign players by attendance. Locked cities stay fixed. Add city spaces or use a template first.</p><div class="preview-list">${proposal.changes.map(c=>`<div class="preview-item"><strong>${esc(c.name)}</strong><small>From: ${esc(slotLabel(c.old))}</small><small>To: ${esc(slotLabel(c.slot))}</small><small>${esc(c.reason)}</small></div>`).join('')}</div><div class="actions">${moved?'<button class="primary" id="applyProposal">Apply '+moved+' changes</button>':''}<button id="cancelProposal">Keep current layout</button></div>`);if(moved)$('#applyProposal').onclick=()=>{commit(()=>state.members=proposal.members);closeModal();toast('Suggested assignments applied. Undo is available.')};$('#cancelProposal').onclick=closeModal};
$('#undoBtn').onclick=()=>{if(!undo.length)return;redo.push(JSON.stringify(state));state=JSON.parse(undo.pop());persist();render()};$('#redoBtn').onclick=()=>{if(!redo.length)return;undo.push(JSON.stringify(state));state=JSON.parse(redo.pop());persist();render()};
function fillSettings(){const f=$('#settingsForm');for(const [k,v] of Object.entries(state.settings)){if(!f.elements[k])continue;if(f.elements[k].type==='checkbox')f.elements[k].checked=v;else f.elements[k].value=v}}
$('#settingsForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),settings={alliance:f.get('alliance').trim(),state:f.get('state').trim(),time1:f.get('time1'),time2:f.get('time2'),anchorX:+f.get('anchorX'),anchorY:+f.get('anchorY'),anchor2X:+f.get('anchor2X'),anchor2Y:+f.get('anchor2Y'),verified:f.has('verified')};const changed=['anchorX','anchorY','anchor2X','anchor2Y'].some(k=>settings[k]!==state.settings[k]);try{const result=changed?Hive.changeMapReference(state,settings):{state:{...state,settings:{...state.settings,...settings}},displaced:[]};const save=()=>{commit(()=>{state=result.state;if(changed)state.members.forEach(m=>{m.confirmed=false;m.verified=false})});closeModal();toast('Settings saved. Fixed world features retain their world coordinates.')};if(result.displaced.length){openModal(`<h2>Update map coordinates?</h2><p>${result.displaced.length} unlocked cities conflict with map features and will return to their queues: ${result.displaced.map(esc).join(', ')}. Your attendance is preserved. Undo is available.</p><button class="primary" id="applyMapReference">Update coordinates</button>`);$('#applyMapReference').onclick=save}else save()}catch(err){toast(err.message)}};
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#backupBtn').onclick=()=>download('bear-hive-backup.json',JSON.stringify(state,null,2),'application/json');$('#restoreBtn').onclick=()=>$('#restoreFile').click();$('#restoreFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Backup is too large.');const restored=Hive.validate(JSON.parse(await file.text()));openModal(`<h2>Restore this plan?</h2><p>${esc(restored.settings.alliance)} · ${restored.members.length} members. This replaces the current draft. Undo will remain available.</p><button class="primary" id="confirmRestore">Restore plan</button>`);$('#confirmRestore').onclick=()=>{commit(()=>state=restored);closeModal();fit();toast('Backup restored')}}catch(err){toast(err.message)}e.target.value=''};
$('#historyBtn').onclick=()=>{openModal(`<h2>Recovery history</h2><p>Recent changes stored on this device. Restore any snapshot, then use Undo if needed.</p><div class="sheet-list">${history.slice(-10).reverse().map((h,i)=>`<button data-history="${history.length-1-i}">${new Date(h.at).toLocaleString()}<small class="muted">${JSON.parse(h.state).members.length} members</small></button>`).join('')||'<p>No earlier snapshots yet.</p>'}</div>`);$$('[data-history]').forEach(b=>b.onclick=()=>{const restored=Hive.validate(JSON.parse(history[+b.dataset.history].state));commit(()=>state=restored);closeModal();fit();toast('Snapshot restored')})};
$('#clearDemo').onclick=()=>{const count=state.members.filter(m=>m.id.startsWith('demo-')).length;openModal(`<h2>Remove sample members?</h2><p>This removes ${count} fictional sample members and preserves anyone you added.</p><button class="danger" id="confirmClear">Remove samples</button>`);$('#confirmClear').onclick=()=>{commit(()=>state.members=state.members.filter(m=>!m.id.startsWith('demo-')));closeModal()}};
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows}
$('#importBtn').onclick=()=>{openModal('<div class="eyebrow">BRING YOUR ROSTER</div><h2>Less typing. More planning.</h2><p>Paste one player name per line, or CSV with columns: name, playerId, trap. Headers are optional. Existing names or player IDs are flagged for review.</p><label>Roster<textarea id="importText" rows="8" placeholder="Caroline,123456,1\n베리별,654321,2"></textarea></label><input id="csvFile" type="file" accept=".csv,.txt,text/csv,text/plain"><div class="actions"><button class="primary" id="previewImport">Preview import</button></div>');$('#csvFile').onchange=async e=>{if(e.target.files[0])$('#importText').value=await e.target.files[0].text()};$('#previewImport').onclick=()=>{let rows=parseCSV($('#importText').value);if(rows[0]&&/^(name|username|player name)$/i.test(rows[0][0].trim()))rows.shift();if(rows.length>500){toast('Import up to 500 members at a time.');return}const knownNames=new Set(state.members.map(m=>m.name.toLowerCase())),knownIds=new Set(state.members.map(m=>m.playerId).filter(Boolean));let ready=[],skipped=[];for(const r of rows){const name=r[0]?.trim(),pid=r[1]?.trim()||'',trap=r[2]?.trim()==='2'?2:1;if(!name)continue;if(knownNames.has(name.toLowerCase())||(pid&&knownIds.has(pid))){skipped.push(name);continue}knownNames.add(name.toLowerCase());if(pid)knownIds.add(pid);ready.push({id:crypto.randomUUID(),name,playerId:pid,trap,role:'both',alliance:state.settings.alliance,whale:false,speed:'unknown',priority:0,attendance:{1:{kind:'unknown',attended:null,total:null},2:{kind:'unknown',attended:null,total:null}},slot:null,current:null,locked:false,confirmed:false,verified:false,joinSeconds:null,rallySeconds:null,notes:''})}openModal(`<h2>${ready.length} members ready.</h2><p>${skipped.length} duplicate names or IDs will be skipped.</p><div class="preview-list">${ready.map(m=>`<div class="preview-item">${esc(m.name)} <small>BT ${m.trap}${m.playerId?' · '+esc(m.playerId):''}</small></div>`).join('')}${skipped.length?'<p>Skipped: '+esc(skipped.join(', '))+'</p>':''}</div><button class="primary" id="confirmImport" ${ready.length?'':'disabled'}>Import members</button>`);$('#confirmImport').onclick=()=>{commit(()=>state.members.push(...ready));closeModal();toast('Roster imported. Set attendance before suggesting assignments.') }}};
function exportCSV(){const rows=[['Name','Player ID','Trap','Row','Assigned X','Assigned Y','Attendance','Current X','Current Y','Relocation confirmed by R4','Officer verified','Coordinate mapping verified'],...state.members.map(m=>{const s=slotBy(m.slot),c=s?Hive.coord(state,s):{};return[m.name,m.playerId,m.trap,s?.row??'',c.x??'',c.y??'',frequencyBadge(m,m.trap),m.current?.x??'',m.current?.y??'',m.confirmed,m.verified,state.settings.verified]})];const safe=v=>{let s=String(v);if(/^[=+@\-]/.test(s))s="'"+s;return'"'+s.replace(/"/g,'""')+'"'};download('bear-hive-assignments.csv','\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
$('#csvBtn').onclick=()=>exportCSV();
async function exportPNG(){try{const trapIds=activeTrap==='all'?[1,2]:[+activeTrap],belongs=o=>o.trap?trapIds.includes(o.trap):(!state.traps.length||trapIds.includes([...state.traps].sort((a,b)=>Math.hypot(o.x-a.x,o.y-a.y)-Math.hypot(o.x-b.x,o.y-b.y))[0]?.id));const traps=state.traps.filter(t=>trapIds.includes(t.id)),slots=state.slots.filter(belongs),blocks=state.blocks.filter(belongs),structures=state.structures.filter(belongs),objects=[...traps,...slots,...blocks,...structures];if(!objects.length){const o=Hive.worldOrigin(state),p=mapSearchPoint||{x:500,y:500};objects.push({x:p.x-o.x-12,y:p.y-o.y-12,w:24,h:24})}const minX=Math.min(...objects.map(o=>o.x))-6,minY=Math.min(...objects.map(o=>o.y))-6,maxX=Math.max(...objects.map(o=>o.x+o.w))+6,maxY=Math.max(...objects.map(o=>o.y+o.h))+6;const canvas=document.createElement('canvas');canvas.width=4096;canvas.height=4096;const ctx=canvas.getContext('2d'),pad=110,header=230,footer=140,scale=Math.min((4096-2*pad)/(maxX-minX),(4096-header-footer)/(maxY-minY)),ox=(4096-(maxX-minX)*scale)/2-minX*scale,oy=header+(4096-header-footer-(maxY-minY)*scale)/2-minY*scale,px=x=>ox+x*scale,py=y=>oy+y*scale;ctx.fillStyle='#ecf0e6';ctx.fillRect(0,0,4096,4096);ctx.fillStyle='#273c32';ctx.font='bold 70px -apple-system, sans-serif';ctx.fillText('Bear Hive · '+(activeTrap==='all'?'Both traps':'Bear Trap '+activeTrap),110,110);ctx.font='32px -apple-system, sans-serif';ctx.fillText('State '+state.settings.state+' · '+new Date().toLocaleDateString('en-GB')+' · Rows run outward from the bear trap',110,170);ctx.strokeStyle='#cfdbc5';ctx.lineWidth=1;for(let x=Math.ceil(minX);x<=maxX;x++){ctx.beginPath();ctx.moveTo(px(x),py(minY));ctx.lineTo(px(x),py(maxY));ctx.stroke()}for(let y=Math.ceil(minY);y<=maxY;y++){ctx.beginPath();ctx.moveTo(px(minX),py(y));ctx.lineTo(px(maxX),py(y));ctx.stroke()}const rect=(o,fill,stroke='#f4f6ed',line=5)=>{ctx.fillStyle=fill;ctx.fillRect(px(o.x),py(o.y),o.w*scale,o.h*scale);ctx.strokeStyle=stroke;ctx.lineWidth=line;ctx.strokeRect(px(o.x),py(o.y),o.w*scale,o.h*scale)};for(const f of Hive.worldFeatures(state,{x:minX,y:minY,w:maxX-minX,h:maxY-minY})){ctx.globalAlpha=[5,6].includes(f.key)?.3:.8;rect(f,f.color,f.color,1)}ctx.globalAlpha=1;for(const b of blocks)rect(b,'#a8b0a0');for(const o of structures){rect(o,'#8a9a7d');ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font='bold '+Math.max(18,scale*.35)+'px sans-serif';ctx.fillText(o.kind==='hq'?'HQ':o.kind==='node'?'Node':'Banner',px(o.x+o.w/2),py(o.y+o.h/2)+10)}for(const s of slots){const m=memberAt(s.id);rect(s,m?(Hive.attendanceScore(state,m,m.trap)>=.7?'#799677':'#b5beaa'):'#e5ebdd',m?'#f4f6ed':'#aabb9c',m?5:2);ctx.fillStyle=m?'#243d30':'#829277';ctx.textAlign='center';let font=Math.min(58,scale*.38),name=m?.name||'Open';const width=scale*1.82;ctx.font='600 '+font+'px -apple-system, sans-serif';while(ctx.measureText(name).width>width&&font>12){font-=1;ctx.font='600 '+font+'px -apple-system, sans-serif'}ctx.fillText(name,px(s.x+1),py(s.y+1)-8);if(m){const c=Hive.coord(state,s);ctx.font=Math.max(14,Math.min(29,scale*.21))+'px -apple-system, sans-serif';ctx.fillText('Row '+s.row+' · X:'+c.x+' Y:'+c.y,px(s.x+1),py(s.y+1)+Math.min(42,scale*.35))}}for(const t of traps){rect(t,'#315840','#fff',7);ctx.fillStyle='#edf1e9';ctx.textAlign='center';ctx.font='bold '+Math.min(75,scale*.65)+'px sans-serif';ctx.fillText('BEAR '+t.id,px(t.x+1.5),py(t.y+1.5));ctx.font=Math.min(34,scale*.3)+'px sans-serif';ctx.fillText('Front row = row 1',px(t.x+1.5),py(t.y+1.5)+Math.min(65,scale*.55))}ctx.fillStyle='#43543f';ctx.textAlign='left';ctx.font='30px sans-serif';ctx.fillText('Full hive export · 4096 × 4096 px · Each city uses its own Bear Trap reference origin',110,4030);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Image could not be created');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bear-hive-'+(activeTrap==='all'?'both':'bt'+activeTrap)+'-4096.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Large 4096 × 4096 map image downloaded.')}catch(e){toast('Image export failed: '+e.message)}}
$('#pngBtn').onclick=()=>{navigate('map');setTimeout(()=>{fit();exportPNG()},40)};
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Copied')}catch{openModal(`<h2>Copy this text</h2><textarea rows="7" id="copyText" readonly>${esc(s)}</textarea>`);$('#copyText').select()}}
$('#shareBtn').onclick=()=>{const published=state.published?new Date(state.published.at).toLocaleString():'No snapshot published yet';openModal(`<div class="eyebrow">SHARE PLAN</div><h2>Share this plan</h2><p>Create a view-only link to this saved version.</p><div class="notice">This app is public. Anyone with your snapshot link can read the data in it.<br><br>Link data includes player names, IDs and notes. Share it only with intended viewers.</div><p>Last snapshot: ${esc(published)}</p><div class="actions"><button class="primary" id="publishSnapshot">Create snapshot link</button><button id="shareCSV">Export assignments</button><button id="shareImage">Download map image</button></div><p>Shared links are snapshots. Later edits and confirmations do not sync.</p>`);$('#publishSnapshot').onclick=()=>{commit(()=>state.published={at:new Date().toISOString()});const shared=JSON.parse(JSON.stringify(state));shared.published=null;const bytes=new TextEncoder().encode(JSON.stringify(shared));let binary='';for(const b of bytes)binary+=String.fromCharCode(b);const link=location.origin+location.pathname+'#plan='+btoa(binary);openModal(`<h2>Your snapshot is ready.</h2><p>Read-only copy · ${state.members.length} members · Anyone with this link can view the snapshot.</p><textarea id="snapshotLink" rows="4" readonly>${esc(link)}</textarea><div class="actions"><button class="primary" id="copySnapshot">Copy link</button><button id="downloadSnapshot">Download snapshot backup</button></div><p>Large rosters create long links. If your messaging app truncates it, share the map image and assignments CSV.</p>`);$('#copySnapshot').onclick=()=>copy(link);$('#downloadSnapshot').onclick=()=>download('bear-hive-snapshot.json',JSON.stringify(shared,null,2),'application/json')};$('#shareCSV').onclick=exportCSV;$('#shareImage').onclick=()=>{closeModal();navigate('map');setTimeout(()=>{fit();exportPNG()},40)}};
$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem(KEY+'-dark',document.body.classList.contains('dark'))};
